; z80ntime.asm: times every Z80N instruction on a real ZX Spectrum Next and checks the flags where the Next's
; VHDL and the documentation disagree.  Generated by build_probe.py (Fern, Fri 6 Nov 2026); see its docstring.
; Run from BASIC (CLEAR 32767: LOAD "" CODE: RANDOMIZE USR 32768); it prints one screen, waits for a key, returns.

PREG    EQU 0x243B              ; nextreg select
PDAT    EQU 0x253B              ; nextreg data
STACK   EQU 0xBD00              ; grows down through BCxx: above SCRATCH's page, below IMTAB
IMTAB   EQU 0xBD00              ; 257 bytes of BEh: IM 2 goes to BEBEh whatever the bus says
HANDLER EQU 0xBEBE
PAD1    EQU 0x9000              ; where JP (C) lands on a Next (user register 7Fh = 40h)
PAD2    EQU 0xBFC0              ; where it lands if the port reads FFh (omse-ai's 48K)
SCRATCH EQU 47872
D35     EQU 119                 ; T-states from the interrupt to a loop, at 3.5 MHz
D28     EQU 147                 ; ... and at 28 MHz (one wait on every read: 28 of them)
O35     EQU 18                  ; INC IY (10) and JP (IX) (8)

        org 0x8000
start:  di
        ld (bas_sp),sp
        ld sp,STACK
        push ix                 ; BASIC's IX and IY, back at the end
        ld (bas_iy),iy
        ld a,i
        ld (bas_i),a
        call cls
        ld hl,s_title
        call pstr
        ld hl,nrsave            ; what the Next is, and what we change
        ld de,nrlist
nr0:    ld a,(de)
        cp 0xFF
        jr z,nr1
        push de
        push hl
        call nr_read
        pop hl
        pop de
        ld (hl),a
        inc hl
        inc de
        jr nr0
nr1:    ld hl,s_wait
        call pstr
        ld hl,SCRATCH           ; the LDxX tests' bytes: zeros
        ld de,SCRATCH+1
        ld bc,255
        ld (hl),0
        ldir
        ld hl,IMTAB             ; the interrupt table, its handler, JP (C)'s pads
        ld de,IMTAB+1
        ld bc,256
        ld (hl),HANDLER/256
        ldir
        ld hl,handler
        ld de,HANDLER
        ld bc,handler_end-handler
        ldir
        ld hl,pad
        ld de,PAD1
        ld bc,2+2
        ldir
        ld hl,pad
        ld de,PAD2
        ld bc,2+2
        ldir
        ; (nextregs through the ports, not NEXTREG: harmless on a Spectrum without them)
        ld a,0xC4               ; only the ULA's frame interrupt
        ld e,0x01
        call nr_write
        ld a,0xC5               ; no CTC
        ld e,0
        call nr_write
        ld a,0xC6               ; no UART
        ld e,0
        call nr_write
        ld a,0x07               ; 3.5 MHz
        ld e,0
        call nr_write
        ld a,0x7F               ; what JP (C) reads
        ld e,0x40
        call nr_write
        call sel7f
        ld a,IMTAB/256
        ld i,a
        im 2
        ; 3.5 MHz: calibrate, then every test
        ld hl,tcal
        call measure            ; (a warm-up)
        ld hl,tcal
        call measure
        ld (ncal),hl
        call times22            ; W35 = n x 22 + 11
        ld bc,11
        add hl,bc
        jr nc,cw1
        inc de
cw1:    ld (w35),hl
        ld (w35+2),de
        ld hl,O35*256
        ld (o88),hl
        ld hl,w35
        ld de,ttab
        ld bc,tres
        call run_table
        ; 28 MHz: the window from the frame, the loop's overhead measured, then the tests
        ld a,0x07               ; 28 MHz
        ld e,0x03
        call nr_write
        ld a,0x07
        call nr_read
        ld (speed28),a
        ld hl,(w35)             ; W28 = 8 x (W35 + D35) - D28
        ld de,(w35+2)
        ld bc,D35
        add hl,bc
        jr nc,cx1
        inc de
cx1:    ld b,3
cx2:    add hl,hl
        rl e
        rl d
        djnz cx2
        ld bc,D28
        or a
        sbc hl,bc
        jr nc,cx3
        dec de
cx3:    ld (w28),hl
        ld (w28+2),de
        ld hl,uempty
        call measure            ; (a warm-up at the new speed)
        ld hl,uempty
        call measure
        ld (nempty),hl
        ld hl,0
        ld (o88),hl
        ld hl,w28
        ld b,h
        ld c,l
        ld hl,(nempty)
        call q88                ; O28 = W28 / n, 8.8
        ld (o88),hl
        ld hl,w28
        ld de,utab
        ld bc,ures
        call run_table
        ; back to how it was
        ld a,(sv07)
        and 3
        ld e,a
        ld a,0x07
        call nr_write
        ld a,(svc4)
        ld e,a
        ld a,0xC4
        call nr_write
        ld a,(svc5)
        ld e,a
        ld a,0xC5
        call nr_write
        ld a,(svc6)
        ld e,a
        ld a,0xC6
        call nr_write
        ld a,(sv7f)
        ld e,a
        ld a,0x7F
        call nr_write
        im 1
        ld a,(bas_i)
        ld i,a
        ld hl,fltab             ; the flags, once each
fl0:    ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,d
        or e
        jr z,fl1
        push hl
        ex de,hl
        call jphl
        pop hl
        ld bc,8                 ; past the address's high byte, the label, the kind and the VHDL's value
        add hl,bc
        jr fl0
fl1:    call report
        call photobeep          ; the photo beep (Melissa O'Neill's idea, Tally Fern's spec; ../beep.inc), added by Hart's-tongue
        call waitkey            ; a photo, then a key (Melissa O'Neill's rule: so it can run from the menu)
        ld iy,(bas_iy)
        pop ix
        ld sp,(bas_sp)
        ei
        ret

jphl:   jp (hl)

waitkey:                        ; any key, through port FEh (interrupts off): let go first, then a press
        xor a
        in a,(0xFE)
        cpl
        and 0x1F
        jr nz,waitkey
wk1:    xor a
        in a,(0xFE)
        cpl
        and 0x1F
        jr z,wk1
        ret

sel7f:  ld bc,PREG              ; select user register 7Fh at 253Bh (for JP (C))
        ld a,0x7F
        out (c),a
        ret

nr_write:                       ; nextreg A = E
        ld bc,PREG
        out (c),a
        inc b
        out (c),e
        ret

nr_read:                        ; A = a nextreg's value
        ld bc,PREG
        out (c),a
        inc b
        in a,(c)
        ret

; Run a table of tests: HL = the window (4 bytes), DE = the table, BC = where the results go (8.8 T each)
run_table:
        ld (rt_w),hl
        ld (rt_res),bc
rt0:    ld a,(de)
        ld l,a
        inc de
        ld a,(de)
        ld h,a
        inc de
        or l
        ret z
        push de
        call sel7f              ; (OUTINB's test writes the select port)
        call measure            ; HL = loops in the window
        ld bc,(rt_w)
        call q88                ; HL = window / n - overhead, 8.8
        pop de
        inc de                  ; past the label
        inc de
        ld a,(de)               ; the helpers' T
        inc de
        inc de                  ; past the prediction
        cp 0xFF
        jr z,rt_hh
        cp 0xFE
        jr z,rt_lp
        push de
        ld d,a                  ; helpers x 256
        ld e,0
        or a
        sbc hl,de
        pop de
        jr rt_st
rt_lp:  push de                 ; the loop itself: put its overhead back
        ld de,(o88)
        add hl,de
        pop de
        jr rt_st
rt_hh:  push de                 ; subtract the measured helpers (the 28 MHz table's second entry)
        ld de,(ures+2)
        or a
        sbc hl,de
        pop de
rt_st:  push de
        ld de,(rt_res)
        ex de,hl
        ld (hl),e
        inc hl
        ld (hl),d
        inc hl
        ld (rt_res),hl
        pop de
        jr rt0

; HL = n, BC = the window's address: HL = (window x 256) / n - (o88), as 8.8 (FFFFh if it won't fit)
q88:    push hl
        ld h,b
        ld l,c
        ld de,dnum+1            ; window << 8
        ld bc,3
        ldir
        xor a
        ld (dnum),a
        pop bc
        call div32
        ld a,(dnum+2)
        ld hl,dnum+3
        or (hl)
        ld hl,0xFFFF
        ret nz
        ld hl,(dnum)
        ld de,(o88)
        or a
        sbc hl,de
        ret

; DE:HL = HL x 22 (= x 16 + x 4 + x 2; under 2^21, so D stays 0)
times22:
        ld de,0
        add hl,hl               ; x 2
        rl e
        push de
        push hl
        add hl,hl               ; x 4
        rl e
        push de
        push hl
        add hl,hl               ; x 8
        rl e
        add hl,hl               ; x 16
        rl e
        pop bc                  ; + x 4
        add hl,bc
        pop bc
        ld a,e
        adc a,c
        ld e,a
        pop bc                  ; + x 2
        add hl,bc
        pop bc
        ld a,e
        adc a,c
        ld e,a
        ret

; (dnum) 4 bytes / BC -> quotient in (dnum); (drem) 3 bytes
div32:  xor a
        ld (drem),a
        ld (drem+1),a
        ld (drem+2),a
        ld (dden),bc
        ld b,32
dv1:    ld hl,dnum
        sla (hl)
        inc hl
        rl (hl)
        inc hl
        rl (hl)
        inc hl
        rl (hl)
        ld hl,drem
        rl (hl)
        inc hl
        rl (hl)
        inc hl
        rl (hl)
        ld hl,(drem)
        ld de,(dden)
        or a
        sbc hl,de
        ld a,(drem+2)
        sbc a,0
        jr c,dv2
        ld (drem),hl
        ld (drem+2),a
        ld hl,dnum
        set 0,(hl)
dv2:    djnz dv1
        ret

; HL = a test's entry: run it from one frame interrupt to the next; HL = how many loops
measure:
        ld (m_go+1),hl
        ld (m_sp),sp
        xor a
        ld (istate),a
        ld iy,0
        ei
        halt                    ; the frame interrupt (its handler's first call returns here)
m_go:   jp 0
m_done: ld sp,(m_sp)            ; (its second call comes here, interrupts off)
        push iy
        pop hl
        ld iy,(bas_iy)
        ret

handler:                        ; copied to HANDLER
        push af
        ld a,(istate)
        or a
        jr nz,h_stop
        inc a
        ld (istate),a
        pop af
        ei
        ret
h_stop: jp m_done
handler_end:

pad:    inc iy                  ; copied to PAD1 and PAD2: JP (C) lands here
        jp (ix)

tcal:   ld ix,tcall             ; the calibration: NOP, 4 T
tcall:  nop
        inc iy
        jp (ix)

uempty: ld ix,uemptyl           ; the loop alone, at 28 MHz
uemptyl:
        inc iy
        jp (ix)

