        push hl
        pop af
        ld hl,47984
        ld (hl),1
        ld bc,0x28FF
        ld a,(bc)
        bit 0,(hl)
        push af
        pop hl
        ld h,0
        ld (flres+12),hl
        ret
flg7:  xor a
        cp 0x28
        nop
        scf
        push af
        pop hl
        ld h,0
        ld (flres+14),hl
        ret
fltab:
        dw flg0
        db "31 F",0
        dw 254
        dw flg1
        db "A5 F",0
        dw 168
        dw flg2
        db "A4 F",0
        dw 237
        dw flg3
        db "B7 F",0
        dw 8
        dw flg4
        db "93HL",1
        dw 16384
        dw flg5
        db "27 F",0
        dw 52
        dw flg6
        db "BITF",0
        dw 16
        dw flg7
        db "SCFF",0
        dw 129
        dw 0
flres: ds 16

; -- printing -------------------------------------------------------------------------------------------
cls:    call 0x0DAF
        ld a,2
        call 0x1601
        ld a,255
        ld (0x5C8C),a           ; SCR_CT: never "scroll?"
        ret

putc:   push bc                 ; A to the screen (A comes back changed)
        push de
        push hl
        rst 0x10
        pop hl
        pop de
        pop bc
        ret

pstr:   ld a,(hl)
        or a
        ret z
        call putc
        inc hl
        jr pstr

phex2:  push af
        rrca
        rrca
        rrca
        rrca
        call phex1
        pop af
phex1:  and 15
        add a,0x90
        daa
        adc a,0x40
        daa
        jp putc

pdec3:                          ; HL = 0..999, right-aligned in three ("###" if more)
        ld de,1000
        or a
        sbc hl,de
        add hl,de
        jr nc,pd_big
        ld c,' '
        ld de,100
        call pd_dig
        ld de,10
        call pd_dig
        ld a,l
        add a,'0'
        jp putc
pd_big: ld hl,s_big
        jp pstr
pd_dig: ld a,'0'-1
pd1:    inc a
        or a
        sbc hl,de
        jr nc,pd1
        add hl,de
        cp '0'
        jr nz,pd2
        ld a,c
        jp putc
pd2:    ld c,'0'
        jp putc

; Print a table's results: DE = the table, HL = its results; B = how many matched (out), C = count (out)
ptable: xor a
        ld (pt_ok),a
        ld (pt_n),a
pt0:    ld a,(de)
        inc de
        ld c,a
        ld a,(de)
        inc de
        or c
        jr z,pt9
        ld a,(de)               ; the label
        inc de
        call putc
        ld a,(de)
        inc de
        call putc
        inc de                  ; the helpers
        ld a,(de)               ; the VHDL's T
        inc de
        ld (pt_pred),a
        push de
        ld e,(hl)               ; the result, 8.8
        inc hl
        ld d,(hl)
        inc hl
        push hl
        ex de,hl
        ld a,h                  ; negative (bit 15): "  -"
        and 0x80
        jr z,pt1
        ld hl,s_neg
        call pstr
        ld a,'?'
        jr pt3
pt1:    ld a,l                  ; the fraction far from whole?
        ld (pt_frac),a
        ld de,0x0080            ; rounded
        add hl,de
        ld l,h
        ld h,0
        push hl
        call pdec3
        pop hl
        ld a,(pt_frac)
        sub 0x41
        cp 0x7F
        ld a,'?'
        jr c,pt3
        ld a,(pt_pred)
        cp l
        ld a,'*'
        jr nz,pt3
        ld a,(pt_ok)
        inc a
        ld (pt_ok),a
        ld a,' '
pt3:    call putc
        ld a,' '
        call putc
        ld a,' '                ; (the ROM's printing changes A)
        call putc
        ld a,(pt_n)
        inc a
        ld (pt_n),a
        pop hl
        pop de
        jr pt0
pt9:    ld a,(pt_ok)
        ld b,a
        ld a,(pt_n)
        ld c,a
        ret

report: call cls
        ld hl,s_title
        call pstr
        ld a,(sv01)             ; core major.minor.sub, machine id, mmu4/5, type, speed
        rrca
        rrca
        rrca
        rrca
        and 15
        add a,'0'
        call putc
        ld a,'.'
        call putc
        ld a,(sv01)
        and 15
        call pdec2z
        ld a,'.'
        call putc
        ld a,(sv0e)
        call pdec2z
        ld hl,s_id
        call pstr
        ld a,(sv00)
        call phex2
        ld hl,s_mmu
        call pstr
        ld a,(sv54)
        call phex2
        ld a,' '
        call putc
        ld a,(sv55)
        call phex2
        ld hl,s_type
        call pstr
        ld a,(sv03)
        call phex2
        ld hl,s_cpu
        call pstr
        ld a,(sv07)
        call phex2
        ld a,'/'
        call putc
        ld a,(speed28)
        call phex2
        ld a,13
        call putc
        ld hl,s_35
        call pstr
        ld de,ttab
        ld hl,tres
        call ptable
        ld (ok35),bc
        ld hl,s_28
        call pstr
        ld de,utab
        ld hl,ures
        call ptable
        ld (ok28),bc
        ld hl,s_fl
        call pstr
        call pflags
        ld (okfl),bc
        ld hl,s_sum             ; the verdict: how many as the VHDL says
        call pstr
        ld bc,(ok35)
        call pfrac
        ld a,' '
        call putc
        ld bc,(ok28)
        call pfrac
        ld a,' '
        call putc
        ld bc,(okfl)
        call pfrac
        ld hl,s_key
        jp pstr

pfrac:  push bc                 ; "B/C"
        ld l,b
        ld h,0
        call pdec2
        ld a,'/'
        call putc
        pop bc
        ld l,c
        ld h,0
        jp pdec2

pdec2z: ld b,'0'-1              ; A = 0..99 as two digits
pz1:    inc b
        sub 10
        jr nc,pz1
        add a,10+'0'
        push af
        ld a,b
        call putc
        pop af
        jp putc

pdec2:  ld de,100               ; HL = 0..99 without leading spaces (or as pdec3 if more)
        or a
        sbc hl,de
        add hl,de
        jp nc,pdec3
        ld de,10
        or a
        sbc hl,de
        add hl,de
        jr c,pdec1
        ld c,'0'
        call pd_dig
pdec1:  ld a,l
        add a,'0'
        jp putc

pflags: xor a                   ; two to a line: "LLLL vv/pp*  " (16)
        ld (pt_ok),a
        ld (pt_n),a
        ld de,fltab
        ld hl,flres
pf0:    ld a,(de)
        inc de
        ld c,a
        ld a,(de)
        inc de
        or c
        jr z,pf9
        ld b,4
pf1:    ld a,(de)
        inc de
        call putc
        djnz pf1
        ld a,' '
        call putc
        ld a,(de)               ; 1: a 16-bit result
        inc de
        ld (pt_frac),a
        ld a,(de)               ; the VHDL's
        ld c,a
        inc de
        ld a,(de)
        ld b,a
        inc de
        push de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        push hl
        push bc
        ld a,(pt_frac)
        or a
        jr z,pf2
        ld a,d
        call phex2
pf2:    ld a,e
        call phex2
        ld a,'/'
        call putc
        pop bc
        ld a,(pt_frac)
        or a
        jr z,pf3
        ld a,b
        call phex2
pf3:    ld a,c
        call phex2
        ld a,e                  ; match?
        cp c
        jr nz,pf4
        ld a,d
        cp b
        jr nz,pf4
        ld a,(pt_ok)
        inc a
        ld (pt_ok),a
        ld a,' '
        jr pf5
pf4:    ld a,'*'
pf5:    call putc
        ld a,(pt_frac)          ; pad to 16
        or a
        ld b,1
        jr nz,pf6
        ld b,5
pf6:    ld a,' '
        call putc
        djnz pf6
        ld a,(pt_n)
        inc a
        ld (pt_n),a
        pop hl
        pop de
        jr pf0
pf9:    ld a,(pt_ok)
        ld b,a
        ld a,(pt_n)
        ld c,a
        ret

s_title: db "Z80NTIME core ",0
s_id:   db " id ",0
s_mmu:  db 13,"mmu ",0
s_type: db " type ",0
s_cpu:  db " cpu ",0
s_wait: db 13,"timing every Z80N instruction...",0
s_35:   db "3.5 MHz, T-states (*: not VHDL)",13,0
s_28:   db "28 MHz, T-states",13,0
s_fl:   db "flags got/VHDL",13,0
s_sum:  db "as VHDL: ",0
s_big:  db "###",0
s_neg:  db "  -",0
s_key:  db " (key)",0

nrlist: db 0x00,0x01,0x0E,0x03,0x07,0x54,0x55,0xC4,0xC5,0xC6,0x7F,0xFF
nrsave:
sv00:   db 0
sv01:   db 0
sv0e:   db 0
sv03:   db 0
sv07:   db 0
sv54:   db 0
sv55:   db 0
svc4:   db 0
svc5:   db 0
svc6:   db 0
sv7f:   db 0
speed28: db 0
bas_sp: dw 0
bas_iy: dw 0
bas_i:  db 0
istate: db 0
m_sp:   dw 0
ncal:   dw 0
nempty: dw 0
w35:    ds 4
w28:    ds 4
o88:    dw 0
rt_w:   dw 0
rt_res: dw 0
dnum:   ds 4
drem:   ds 3
dden:   dw 0
pt_ok:  db 0
pt_n:   db 0
pt_pred: db 0
pt_frac: db 0
ok35:   dw 0
ok28:   dw 0
okfl:   dw 0
TAPEID  equ 60                ; the photo beep's tape ID (../NOTES.md, "The photo beep")
        include "../beep.inc"
endcode:
